using System;
using Content.Server.Parallax;
using Content.Shared.Parallax.Biomes;
using Robust.Shared.Prototypes;

namespace Content.Server._Aspis.Organizations;

/// <summary>
/// Isolated, round-local planetary destinations for faction relay work. Do not
/// reuse public salvage destinations: the disk and the assigned shuttle are the
/// only authorized way into the work site. Its physical grid is generated by
/// the fork's normal BiomeSystem when players approach.
/// </summary>
public sealed partial class OrganizationSystem
{
    private const string FactionPlanetBiome = "Grasslands";
    private const int MaxFactionPlanetMapsPerRound = 2;
    private int _factionPlanetMapsCreatedThisRound;

    private bool TryCreateFactionPlanetSite(SectorQuotaClaim claim)
    {
        claim.FactionCreationError = string.Empty;
        if (_factionPlanetMapsCreatedThisRound >= MaxFactionPlanetMapsPerRound)
        {
            claim.FactionCreationError = "У цьому раунді більше немає вільних планетарних експедиційних місць.";
            return false;
        }
        if (!_prototypes.TryIndex<BiomeTemplatePrototype>(FactionPlanetBiome, out var biome))
        {
            claim.FactionCreationError = "Сервер не завантажив необхідний біом експедиційної планети.";
            return false;
        }

        EntityUid? created = null;
        var success = false;
        try
        {
            created = _organizationMapSystem.CreateMap(out var mapId);
            EntityManager.System<BiomeSystem>().EnsurePlanet(created.Value, biome);
            var name = $"Планетарна експедиція {claim.FactionSiteCode}";
            _organizationMetadata.SetEntityName(created.Value, name);
            if (!_organizationShuttle.TryAddFTLDestination(mapId, true, true, false, out _))
            {
                claim.FactionCreationError = "Не вдалося зареєструвати маршрут FTL до експедиційної планети.";
                return false;
            }

            var route = EnsureComp<AspisFactionExpeditionDestinationComponent>(created.Value);
            route.Organization = claim.Organization;
            route.Assignment = claim.FactionAssignmentId;
            route.LaunchReadyAt = _gameTiming.CurTime + FactionWreckLaunchDelay;
            claim.FactionPlanetMap = created;
            claim.FactionPlanetName = name;
            claim.FactionWreckLaunchReadyAt = route.LaunchReadyAt;
            _factionPlanetMapsCreatedThisRound++;
            success = true;
            _adminLog.Add(Content.Shared.Database.LogType.Action,
                Content.Shared.Database.LogImpact.Low,
                $"Faction planet created: {claim.Code}, map={mapId}, org={claim.Organization}");
            return true;
        }
        catch (Exception ex)
        {
            claim.FactionCreationError = "Створення планети завершилося внутрішньою помилкою. " +
                $"Причина: {ex.GetType().Name}. Подробиці в журналі сервера.";
            _log.GetSawmill("organizations.faction-sites")
                .Error($"Unable to prepare faction planet {claim.Code}: {ex}");
            return false;
        }
        finally
        {
            if (!success && created is { } map && !TerminatingOrDeleted(map))
                QueueDel(map);
        }
    }

    private static EntityUid? FactionDestinationMap(SectorQuotaClaim claim) =>
        claim.FactionWreckMap ?? claim.FactionPlanetMap;

    private static bool FactionTravelVisited(SectorQuotaClaim claim) =>
        claim.FactionWreckVisited || claim.FactionPlanetVisited;
}
